insert into public.tools (
 name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,
 korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,korean_tested,verification_level,verification_notes,
 is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at
)
select s.name,s.description,s.full_description,s.url,
 regexp_replace(s.url,'^(https?://[^/]+).*$','\1/favicon.ico'),
 s.pricing_type,s.pricing_start_at,s.pricing_summary,array[s.pricing_summary],'USD',s.verification_sources[1],now(),
 s.korean_support_level,true,true,false,false,false,'official_sources',
 '공식 제품·가격·지원 문서를 확인했습니다. 계정 생성, 실제 생성 결과, 한국어 품질과 API 호출은 직접 테스트하지 않았습니다.',
 false,s.has_api,s.api_url,s.ai_type,s.tool_scope,s.primary_features,array[]::text[],s.primary_features,
 array['해당 전문 기능이 필요한 개인과 팀'],
 array['AI 출력은 정확성·저작권·개인정보를 사용자가 검토해야 합니다.','가격과 제공 한도는 지역·결제 주기·정책 변경에 따라 달라질 수 있습니다.'],
 s.verification_sources,now(),now()
from _tool_seed_055 s
where not exists(select 1 from public.tools t where lower(t.url)=lower(s.url) or lower(t.name)=lower(s.name));

insert into public.tool_categories(tool_id,category_id)
select t.id,c.id
from _tool_seed_055 s
join public.tools t on lower(t.url)=lower(s.url)
cross join lateral unnest(array_remove(array[s.primary_category,s.secondary_category],null)) as category_slug(slug)
join public.categories c on c.slug=category_slug.slug
on conflict(tool_id,category_id) do nothing;
